/**
 * Minimal, dependency-free Markdown renderer for model output.
 *
 * Safety model: every piece of untrusted text is escaped *before* any markup
 * is introduced, and only a small set of tags/attributes is generated by this
 * module. Links must use http(s) or mailto. Raw HTML in the source is inert.
 */

const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const SAFE_URL = /^(https?:\/\/|mailto:)/i;

export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (ch) => ESCAPES[ch]);
}

function inline(source) {
  const code = [];
  let text = String(source ?? '');
  text = text.replace(/`([^`\n]+)`/g, (_, snippet) => {
    code.push(snippet);
    return `\u0000${code.length - 1}\u0000`;
  });

  text = escapeHtml(text);

  text = text.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (match, label, href) => {
    const url = href.replace(/&amp;/g, '&');
    if (!SAFE_URL.test(url)) return match;
    return `<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
  });

  text = text.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  text = text.replace(/__([^_]+)__/g, '<strong>$1</strong>');
  text = text.replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, '$1<em>$2</em>');
  text = text.replace(/(^|[^\w])_([^_\n]+)_(?!\w)/g, '$1<em>$2</em>');
  text = text.replace(/~~([^~]+)~~/g, '<del>$1</del>');

  text = text.replace(/\u0000(\d+)\u0000/g, (_, index) => `<code>${escapeHtml(code[Number(index)])}</code>`);
  return text;
}

function codeBlock(body, lang) {
  const language = escapeHtml(lang || 'text');
  return (
    '<div class="codeblock">' +
    `<div class="code-head"><span class="code-lang">${language}</span>` +
    '<button type="button" class="code-copy">复制</button></div>' +
    `<pre><code>${escapeHtml(body)}</code></pre>` +
    '</div>'
  );
}

function isSeparatorRow(line) {
  const cells = splitRow(line);
  return cells.length > 0 && cells.every((cell) => /^:?-{2,}:?$/.test(cell.replace(/\s/g, '')));
}

function splitRow(line) {
  let text = line.trim();
  if (text.startsWith('|')) text = text.slice(1);
  if (text.endsWith('|')) text = text.slice(0, -1);
  return text.split('|').map((cell) => cell.trim());
}

function renderTable(header, rows) {
  const head = header.map((cell) => `<th>${inline(cell)}</th>`).join('');
  const body = rows
    .map((row) => `<tr>${row.map((cell) => `<td>${inline(cell)}</td>`).join('')}</tr>`)
    .join('');
  return `<div class="table-wrap"><table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`;
}

const LIST_UL = /^\s{0,3}[-*+]\s+(.*)$/;
const LIST_OL = /^\s{0,3}(\d+)[.)]\s+(.*)$/;
const HEADING = /^\s{0,3}(#{1,6})\s+(.*)$/;
const HR = /^\s{0,3}([-*_])(?:\s*\1){2,}\s*$/;

function isBlockStart(line) {
  return (
    /^\s{0,3}```/.test(line) ||
    HEADING.test(line) ||
    HR.test(line) ||
    /^\s{0,3}>/.test(line) ||
    LIST_UL.test(line) ||
    LIST_OL.test(line) ||
    (line.includes('|') && isSeparatorRow(line))
  );
}

export function renderMarkdown(source) {
  const text = String(source ?? '')
    .replace(/\r\n?/g, '\n')
    .replace(/\u0000/g, '');
  const lines = text.split('\n');
  const out = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    if (!line.trim()) {
      i += 1;
      continue;
    }

    const fence = /^\s{0,3}```([\w+#.-]*)\s*$/.exec(line);
    if (fence) {
      const lang = fence[1] || '';
      const body = [];
      i += 1;
      while (i < lines.length && !/^\s{0,3}```\s*$/.test(lines[i])) {
        body.push(lines[i]);
        i += 1;
      }
      if (i < lines.length) i += 1;
      out.push(codeBlock(body.join('\n'), lang));
      continue;
    }

    if (HR.test(line)) {
      out.push('<hr>');
      i += 1;
      continue;
    }

    const heading = HEADING.exec(line);
    if (heading) {
      const level = heading[1].length;
      out.push(`<h${level}>${inline(heading[2])}</h${level}>`);
      i += 1;
      continue;
    }

    if (/^\s{0,3}>/.test(line)) {
      const quoted = [];
      while (i < lines.length && /^\s{0,3}>/.test(lines[i])) {
        quoted.push(lines[i].replace(/^\s{0,3}>\s?/, ''));
        i += 1;
      }
      out.push(`<blockquote>${inline(quoted.join(' '))}</blockquote>`);
      continue;
    }

    if (LIST_UL.test(line) || LIST_OL.test(line)) {
      const ordered = LIST_OL.test(line) && !LIST_UL.test(line);
      const pattern = ordered ? LIST_OL : LIST_UL;
      const items = [];
      while (i < lines.length && pattern.test(lines[i])) {
        const match = pattern.exec(lines[i]);
        items.push(inline(ordered ? match[2] : match[1]));
        i += 1;
        while (i < lines.length && /^\s{2,}\S/.test(lines[i]) && !pattern.test(lines[i]) && !isBlockStart(lines[i])) {
          items[items.length - 1] += ` ${inline(lines[i].trim())}`;
          i += 1;
        }
      }
      const tag = ordered ? 'ol' : 'ul';
      out.push(`<${tag}>${items.map((item) => `<li>${item}</li>`).join('')}</${tag}>`);
      continue;
    }

    if (line.includes('|') && i + 1 < lines.length && isSeparatorRow(lines[i + 1])) {
      const header = splitRow(line);
      const rows = [];
      i += 2;
      while (i < lines.length && lines[i].includes('|') && lines[i].trim()) {
        rows.push(splitRow(lines[i]));
        i += 1;
      }
      out.push(renderTable(header, rows));
      continue;
    }

    const paragraph = [];
    while (i < lines.length && lines[i].trim() && !(paragraph.length && isBlockStart(lines[i]))) {
      paragraph.push(lines[i].trim());
      i += 1;
    }
    out.push(`<p>${inline(paragraph.join('\n'))}</p>`);
  }

  return out.join('\n');
}
